window.DP.L10N["sk"] = {"ui":{"Velikost písma: {v}":"Veľkosť písma: {v}","Váš prohlížeč neumí číst nahlas.":"Váš prehliadač nevie čítať nahlas.","Zastavit čtení":"Zastaviť čítanie","Přečíst nahlas":"Prečítať nahlas","Mluvit":"Hovoriť","Poslouchám… klepněte pro konec":"Počúvam… ťuknite pre koniec","Tento prohlížeč diktování neumí. Klepněte do pole a použijte mikrofon na klávesnici telefonu.":"Tento prehliadač nevie diktovať. Ťuknite do poľa a použite mikrofón na klávesnici telefónu.","Povolte prosím mikrofon pro tuto stránku v nastavení prohlížeče.":"Povoľte, prosím, mikrofón pre túto stránku v nastaveniach prehliadača.","Diktování je vypnuté. Na iPhonu zapněte Siri a diktování v Nastavení, nebo použijte mikrofon na klávesnici.":"Diktovanie je vypnuté. Na iPhone zapnite Siri a diktovanie v Nastaveniach alebo použite mikrofón na klávesnici.","Nic jsem neslyšel. Klepněte na Mluvit a mluvte prosím blíž k telefonu.":"Nič som nepočul. Ťuknite na Hovoriť a hovorte, prosím, bližšie k telefónu.","Nenašel jsem mikrofon. Zkontrolujte, že ho nepoužívá jiná aplikace.":"Nenašiel som mikrofón. Skontrolujte, či ho nepoužíva iná aplikácia.","Diktování potřebuje internet. Zkuste to znovu, nebo dotaz napište.":"Diktovanie potrebuje internet. Skúste to znova alebo otázku napíšte.","Diktování v tomto jazyce tu není dostupné. Použijte mikrofon na klávesnici.":"Diktovanie v tomto jazyku tu nie je dostupné. Použite mikrofón na klávesnici.","Zkontrolujte prosím text. Pokud sedí, stiskněte tlačítko pro odeslání.":"Skontrolujte, prosím, text. Ak sedí, stlačte tlačidlo na odoslanie.","Diktování se nepodařilo spustit. Zkuste to prosím znovu.":"Diktovanie sa nepodarilo spustiť. Skúste to, prosím, znova.","Zavolat":"Zavolať","Dobré ráno!":"Dobré ráno!","Dobrý večer!":"Dobrý večer!","Dobrý den!":"Dobrý deň!","Napište prosím svůj dotaz.":"Napíšte, prosím, svoju otázku.","Napište, s čím potřebujete pomoct":"Napíšte, s čím potrebujete pomôcť","Zeptat se":"Opýtať sa","Volá mi někdo z banky":"Volá mi niekto z banky","Přišla mi divná SMS o balíku":"Prišla mi čudná SMS o balíku","Co je Facebook?":"Čo je Facebook?","Jak poslat fotku vnoučatům?":"Ako poslať fotku vnúčatám?","Zapomněl/a jsem heslo":"Zabudol/a som heslo","Telefon se rychle vybíjí":"Telefón sa rýchlo vybíja","Váš vlídný průvodce":"Váš vľúdny sprievodca","S čím vám mohu dnes pomoci?":"S čím vám dnes môžem pomôcť?","Technologie bez stresu, spěchu a obav. Vše vysvětlíme česky, pomalu a krok za krokem.":"Technológie bez stresu, zhonu a obáv. Všetko vysvetlíme pomaly a krok za krokom.","Například: Jak poslat fotku?":"Napríklad: Ako poslať fotku?","Usměvavá paní s brýlemi drží chytrý telefon.":"Usmievavá pani s okuliarmi drží smartfón.","Bez obav":"Bez obáv","Technologie bez stresu":"Technológie bez stresu","Ptejte se snadno":"Pýtajte sa ľahko","Žádná otázka není hloupá. Napište ji, nebo ji řekněte nahlas tlačítkem ":"Žiadna otázka nie je hlúpa. Napíšte ju alebo ju povedzte nahlas tlačidlom ","Hlavní pomocníci":"Hlavní pomocníci","Zeptejte se":"Opýtajte sa","Rozhovor s parťákem. Přednostně odpovídá ověřenými radami, jiné odpovědi jasně označí.":"Rozhovor s parťákom. Prednostne odpovedá overenými radami, iné odpovede jasne označí.","Otevřít rozhovor":"Otvoriť rozhovor","Žádná otázka není hloupá":"Žiadna otázka nie je hlúpa","Je to podvod?":"Je to podvod?","Přišla vám divná SMS nebo e-mail? Společně zkontrolujeme varovné znaky.":"Prišla vám čudná SMS alebo e-mail? Spoločne skontrolujeme varovné znaky.","Zkontrolovat zprávu":"Skontrolovať správu","Text nikam neodesíláme":"Text nikam neodosielame","Krok za krokem":"Krok za krokom","Jednoduché návody. Vždy jen jeden krok na obrazovce.":"Jednoduché návody. Vždy len jeden krok na obrazovke.","Prohlédnout návody":"Pozrieť návody","Pomalu, jak vám vyhovuje":"Pomaly, ako vám vyhovuje","Časté otázky":"Časté otázky","Klepněte a hned dostanete odpověď.":"Ťuknite a hneď dostanete odpoveď.","Vaše bezpečí je na 1. místě":"Vaša bezpečnosť je na 1. mieste","Nikdy po vás nechceme hesla, PIN ani číslo karty.":"Nikdy od vás nechceme heslá, PIN ani číslo karty.","Parťák odpovídá z knihovny ověřených rad. Každou jinou odpověď jasně označí, abyste si ji mohli ověřit.":"Parťák odpovedá z knižnice overených rád. Každú inú odpoveď jasne označí, aby ste si ju mohli overiť.","Vaše dotazy zůstávají jen ve vašem zařízení.":"Vaše otázky zostávajú len vo vašom zariadení.","Usměvavý pán s brýlemi pracuje na tabletu.":"Usmievavý pán s okuliarmi pracuje na tablete.","Chcete mluvit s člověkem?":"Chcete hovoriť s človekom?","Senior telefon je zdarma a nonstop.":"Senior telefon (česká linka pre seniorov) je zadarmo a nonstop.","Další čísla pomoci":"Ďalšie čísla pomoci","Přizpůsobit aplikaci":"Prispôsobiť aplikáciu","Velikost písma, vysoký kontrast, čtení nahlas":"Veľkosť písma, vysoký kontrast, čítanie nahlas","Rozhovor s DIGI parťákem":"Rozhovor s DIGI parťákom","Napište svůj dotaz…":"Napíšte svoju otázku…","Zeptejte se parťáka":"Opýtajte sa parťáka","Ověřené rady mají zelený štítek":"Overené rady majú zelený štítok","Rozhovor jsem smazal.":"Rozhovor som vymazal.","Nový rozhovor":"Nový rozhovor","Do chatu nikdy nepište hesla, PIN ani číslo karty. Rozhovor se neukládá a po zavření aplikace zmizí.":"Do chatu nikdy nepíšte heslá, PIN ani číslo karty. Rozhovor sa neukladá a po zatvorení aplikácie zmizne.","Váš dotaz":"Vaša otázka","Odeslat":"Odoslať","Myslíte jedno z těchto témat?":"Myslíte jednu z týchto tém?","Promiňte, nerozuměl jsem.":"Prepáčte, nerozumel som.","Promiňte, na tohle teď nemám odpověď.":"Prepáčte, na toto teraz nemám odpoveď.","V aplikaci to nemám, hledám odpověď mimo aplikaci…":"V aplikácii to nemám, hľadám odpoveď mimo aplikácie…","Nenašli jste, co jste hledali?":"Nenašli ste, čo ste hľadali?","Zeptat se mimo aplikaci":"Opýtať sa mimo aplikácie","Pozor: {t}":"Pozor: {t}","DIGI parťák říká: ":"DIGI parťák hovorí: ","Vy: ":"Vy: ","Dobrý den! Jsem DIGI parťák.":"Dobrý deň! Som DIGI parťák.","Zeptejte se vlastními slovy, nebo si vyberte téma. Nejdřív hledám v knihovně ověřených rad. Když tam odpověď není, zkusím poradit jinak – ale vždy vás upozorním, ať si to ověříte.":"Pýtajte sa vlastnými slovami alebo si vyberte tému. Najprv hľadám v knižnici overených rád. Keď tam odpoveď nie je, skúsim poradiť inak – ale vždy vás upozorním, aby ste si to overili.","Dobrý den! Jsem DIGI parťák. Zeptejte se vlastními slovy, nebo si vyberte téma.":"Dobrý deň! Som DIGI parťák. Pýtajte sa vlastnými slovami alebo si vyberte tému.","číslo karty":"číslo karty","rodné číslo":"rodné číslo","heslo nebo kód":"heslo alebo kód"," Pozor na citlivé údaje":" Pozor na citlivé údaje","Ve vaší zprávě bylo {what}. Skryl jsem to a nikam se to neodeslalo.":"Vaša správa obsahovala: {what}. Skryl som to a nikam sa to neodoslalo.","Tyto údaje prosím nikdy nikomu nepište – ani do chatu, ani do SMS či e-mailu.":"Tieto údaje, prosím, nikdy nikomu nepíšte – ani do chatu, ani do SMS či e-mailu.","Jste bez internetu.":"Ste bez internetu.","Bez internetu umím odpovídat jen z knihovny ověřených rad. Vyberte si téma, nebo to zkuste znovu, až budete připojeni.":"Bez internetu viem odpovedať len z knižnice overených rád. Vyberte si tému alebo to skúste znova, keď budete pripojení.","V ověřené knihovně to není a odpověď mimo aplikaci se teď nepodařilo získat. Zkuste to za chvíli, napište to jinými slovy, nebo se zeptejte člověka.":"V overenej knižnici to nie je a odpoveď mimo aplikácie sa teraz nepodarilo získať. Skúste to o chvíľu, napíšte to inými slovami alebo sa opýtajte človeka.","Zkuste to napsat jinými slovy, vyberte si téma, nebo se zeptejte člověka.":"Skúste to napísať inými slovami, vyberte si tému alebo sa opýtajte človeka.","Možná hledáte:":"Možno hľadáte:","Senior telefon 800 157 157":"Senior telefon 800 157 157","Promiňte, na tohle nemám ověřenou odpověď. Nechci vám radit nepřesně.":"Prepáčte, na toto nemám overenú odpoveď. Nechcem vám radiť nepresne.","Informace mimo aplikaci – ověřte si ji":"Informácia mimo aplikácie – overte si ju","Tohle v ověřené knihovně DIGI parťáka není. Odpověď připravila umělá inteligence z obecných znalostí. Může obsahovat chybu nebo být zastaralá.":"Toto v overenej knižnici DIGI parťáka nie je. Odpoveď pripravila umelá inteligencia zo všeobecných znalostí. Môže obsahovať chybu alebo byť zastaraná.","Jak si to ověřit:":"Ako si to overiť:","Zeptejte se blízkého člověka, kterému věříte.":"Opýtajte sa blízkeho človeka, ktorému dôverujete.","Podívejte se na oficiální web instituce – adresu napište sami.":"Pozrite sa na oficiálny web inštitúcie – adresu napíšte sami.","Zavolejte bezplatně na Senior telefon 800 157 157.":"Zavolajte bezplatne na Senior telefon 800 157 157 (česká linka).","Než cokoli zaplatíte nebo nainstalujete, nejdřív si informaci ověřte.":"Než čokoľvek zaplatíte alebo nainštalujete, najprv si informáciu overte."," Důležité – jednejte hned":" Dôležité – konajte hneď","Ověřená rada":"Overená rada","Odkud to víme":"Odkiaľ to vieme","Mohlo by vás zajímat:":"Mohlo by vás zaujímať:","Sem vložte nebo opište text podezřelé zprávy…":"Sem vložte alebo odpíšte text podozrivej správy…","Nejdřív prosím vložte text zprávy.":"Najprv, prosím, vložte text správy.","Text jsem vložil.":"Text som vložil.","Schránka je prázdná.":"Schránka je prázdna.","Vložte text podržením prstu v poli a volbou „Vložit“.":"Text vložíte podržaním prsta v poli a voľbou „Vložiť“.","Vložit zkopírovaný text":"Vložiť skopírovaný text","Vložte text podezřelé zprávy, nebo nahrajte její fotku či snímek obrazovky. Ukážu vám varovné znaky a poradím, co bezpečně udělat.":"Vložte text podozrivej správy alebo nahrajte jej fotku či snímku obrazovky. Ukážem vám varovné znaky a poradím, čo bezpečne urobiť.","Zkontrolovat fotku zprávy":"Skontrolovať fotku správy","Udělejte snímek obrazovky podezřelé SMS, e-mailu nebo zprávy a nahrajte ho sem. Můžete zprávu i vyfotit jiným telefonem.":"Urobte snímku obrazovky podozrivej SMS, e-mailu alebo správy a nahrajte ju sem. Správu môžete aj odfotiť iným telefónom.","Nahrát snímek obrazovky":"Nahrať snímku obrazovky","Vyfotit zprávu":"Odfotiť správu","Fotka se odešle k rozboru umělé inteligenci (Claude od firmy Anthropic). Nikde ji neukládáme. Číslo karty nebo kódy na fotce raději zakryjte.":"Fotka sa odošle na rozbor umelej inteligencii (Claude od firmy Anthropic). Nikde ju neukladáme. Číslo karty alebo kódy na fotke radšej zakryte.","Nevíte, jak udělat snímek obrazovky? ":"Neviete, ako urobiť snímku obrazovky? ","Návod pro Android":"Návod pre Android","Návod pro iPhone":"Návod pre iPhone","Nebo vložte text zprávy":"Alebo vložte text správy","Text zprávy":"Text správy","Kontrola textu probíhá jen ve vašem zařízení. Text nikam neodesíláme.":"Kontrola textu prebieha len vo vašom zariadení. Text nikam neodosielame.","Zkontrolovat text":"Skontrolovať text","Vymazat":"Vymazať","Vyzkoušet na ukázkové podvodné SMS":"Vyskúšať na ukážkovej podvodnej SMS","Zlaté pravidlo":"Zlaté pravidlo","Když zpráva spěchá a chce peníze nebo údaje – ":"Keď správa súri a chce peniaze alebo údaje – ","zastavte se a ověřte si to sami.":"zastavte sa a overte si to sami.","Zavolejte bance, poště nebo úřadu na číslo z jejich oficiálního webu nebo z platební karty – nikdy na číslo či odkaz ze zprávy.":"Zavolajte banke, pošte alebo úradu na číslo z ich oficiálneho webu alebo z platobnej karty – nikdy na číslo či odkaz zo správy.","Vyberte prosím obrázek.":"Vyberte, prosím, obrázok.","Obrázek je moc velký. Zkuste udělat snímek obrazovky.":"Obrázok je príliš veľký. Skúste urobiť snímku obrazovky.","Tento obrázek neumím otevřít. Zkuste snímek obrazovky ve formátu JPG nebo PNG.":"Tento obrázok neviem otvoriť. Skúste snímku obrazovky vo formáte JPG alebo PNG.","Prohlížím fotku… může to trvat až půl minuty.":"Prezerám fotku… môže to trvať až pol minúty.","Náhled nahrané fotky zprávy":"Náhľad nahranej fotky správy","Jste bez internetu. Rozbor fotky potřebuje internet – zkuste prosím opsat text zprávy do pole níže.":"Ste bez internetu. Rozbor fotky potrebuje internet – skúste, prosím, odpísať text správy do poľa nižšie.","Rozbor fotky se teď nepodařil. Zkuste to prosím za chvíli, nebo opište text zprávy do pole níže.":"Rozbor fotky sa teraz nepodaril. Skúste to, prosím, o chvíľu alebo odpíšte text správy do poľa nižšie.","Velmi podezřelé!":"Veľmi podozrivé!","Zpráva má několik typických znaků podvodu. Na nic neklikejte a nic neplaťte.":"Správa má niekoľko typických znakov podvodu. Na nič neklikajte a nič neplaťte.","Buďte opatrní":"Buďte opatrní","Našel jsem varovné znaky. Než cokoli uděláte, ověřte si zprávu jinou cestou.":"Našiel som varovné znaky. Než čokoľvek urobíte, overte si správu inou cestou.","Nenašel jsem typické znaky podvodu":"Nenašiel som typické znaky podvodu","To ale neznamená, že je zpráva určitě v pořádku. Podvodníci vymýšlejí stále nové triky.":"To ale neznamená, že je správa určite v poriadku. Podvodníci vymýšľajú stále nové triky.","Fotku se nepodařilo posoudit":"Fotku sa nepodarilo posúdiť","Na fotce nevidím čitelnou zprávu. Zkuste ostřejší snímek obrazovky, na kterém je celý text, nebo text opište do pole.":"Na fotke nevidím čitateľnú správu. Skúste ostrejšiu snímku obrazovky s celým textom alebo text odpíšte do poľa.","Pokud vás zpráva o něco žádá, ověřte si to u odesílatele na známém čísle.":"Ak vás správa o niečo žiada, overte si to u odosielateľa na známom čísle.","Nikdy nezadávejte PIN, hesla ani kódy z SMS přes odkaz.":"Nikdy nezadávajte PIN, heslá ani kódy z SMS cez odkaz.","Na odkaz ve zprávě neklikejte a neodpovídejte.":"Na odkaz v správe neklikajte a neodpovedajte.","Ověřte si to sami – zavolejte na oficiální číslo instituce nebo blízkému člověku.":"Overte si to sami – zavolajte na oficiálne číslo inštitúcie alebo blízkemu človeku.","Zprávu smažte a odesílatele zablokujte.":"Správu vymažte a odosielateľa zablokujte.","Pokud jste už něco vyplnili nebo zaplatili, hned volejte svou banku.":"Ak ste už niečo vyplnili alebo zaplatili, hneď volajte svoju banku.","Rozbor fotky pomocí umělé inteligence. Výsledek je orientační, ověřte si ho. ":"Rozbor fotky pomocou umelej inteligencie. Výsledok je orientačný, overte si ho. ","Co udělat: {t}":"Čo urobiť: {t}","Rozbor fotky pomocí umělé inteligence":"Rozbor fotky pomocou umelej inteligencie","Výsledek je orientační a může obsahovat chybu. Když si nejste jistí, ověřte si to u blízkého nebo na Senior telefonu 800 157 157.":"Výsledok je orientačný a môže obsahovať chybu. Keď si nie ste istí, overte si to u blízkeho alebo na Senior telefone 800 157 157.","Výsledek kontroly":"Výsledok kontroly","Čeho jsem si všiml:":"Čoho som si všimol:","Co teď bezpečně udělat:":"Čo teraz bezpečne urobiť:","Text, který jsem na fotce přečetl":"Text, ktorý som na fotke prečítal","Už jsem klikl/a – co teď?":"Už som klikol/a – čo teraz?","Návody krok za krokem":"Návody krok za krokom","Vyberte si, co se chcete naučit. Na každé obrazovce je jen jeden krok. Můžete se kdykoli vrátit.":"Vyberte si, čo sa chcete naučiť. Na každej obrazovke je len jeden krok. Kedykoľvek sa môžete vrátiť.","{n} kroků · asi {m} min":"{n} krokov · asi {m} min","Všechny návody":"Všetky návody","Začít":"Začať","Zdroj: {t}":"Zdroj: {t}","Postup návodem":"Postup návodom","Krok {i} z {n}":"Krok {i} z {n}","Tip: ":"Tip: ","Krok {i}":"Krok {i}","Zvládli jste to!":"Zvládli ste to!","Výborně. Návod si můžete kdykoli zopakovat.":"Výborne. Návod si môžete kedykoľvek zopakovať.","Zpět":"Späť","Další krok":"Ďalší krok","Hotovo":"Hotovo","Pomoc a důležitá čísla":"Pomoc a dôležité čísla","Klepnutím na číslo rovnou zavoláte. Ve vážné situaci neváhejte – raději zavolejte.":"Ťuknutím na číslo rovno zavoláte. V nebezpečnej situácii neváhajte – radšej zavolajte.","Tísňová volání":"Tiesňové volania","Když potřebujete poradit nebo si promluvit":"Keď potrebujete poradiť alebo sa porozprávať"," Ztratili jste kartu nebo vás někdo okradl?":" Stratili ste kartu alebo vás niekto okradol?","Hned zavolejte do své banky a kartu zablokujte. Číslo najdete na webu banky nebo ve smlouvě.":"Hneď zavolajte do svojej banky a kartu zablokujte. Číslo nájdete na webe banky alebo v zmluve.","Krádež nebo podvod oznamte Policii ČR na čísle 158.":"Krádež alebo podvod oznámte českej polícii na čísle 158.","Čísla připravena podle oficiálních zdrojů (IZS, Život 90, Elpida). Před zveřejněním aplikace je ověřte.":"Čísla pripravené podľa oficiálnych zdrojov (IZS, Život 90, Elpida). Pred zverejnením aplikácie ich overte.","zapnuto":"zapnuté","vypnuto":"vypnuté","Zapnuto":"Zapnuté","Vypnuto":"Vypnuté","Nastavení":"Nastavenia","Upravte si parťáka tak, aby se vám dobře četl a používal.":"Upravte si parťáka tak, aby sa vám dobre čítal a používal.","Jazyk":"Jazyk","Velikost písma":"Veľkosť písma","Ukázka: Takhle velké bude písmo v celé aplikaci.":"Ukážka: Takto veľké bude písmo v celej aplikácii.","Vysoký kontrast":"Vysoký kontrast","Výraznější barvy a silnější okraje pro horší zrak.":"Výraznejšie farby a hrubšie okraje pre horší zrak.","Číst odpovědi nahlas":"Čítať odpovede nahlas","Parťák vám každou odpověď v chatu sám přečte.":"Parťák vám každú odpoveď v chate sám prečíta.","Pomalejší čtení":"Pomalšie čítanie","Hlas bude mluvit pomaleji a zřetelněji.":"Hlas bude hovoriť pomalšie a zreteľnejšie.","Parťák na ploše telefonu":"Parťák na ploche telefónu"," Aplikace je nainstalovaná. Výborně!":" Aplikácia je nainštalovaná. Výborne!","Přidejte si DIGI parťáka na plochu. Otevřete ho pak jedním klepnutím, jako každou jinou aplikaci.":"Pridajte si DIGI parťáka na plochu. Potom ho otvoríte jedným ťuknutím ako každú inú aplikáciu.","Hotovo! Parťák je na ploše.":"Hotovo! Parťák je na ploche.","Přidat na plochu":"Pridať na plochu","Návod krok za krokem":"Návod krok za krokom","Soukromí a bezpečí":"Súkromie a bezpečnosť","Aplikace nemá žádný účet ani registraci.":"Aplikácia nemá žiadny účet ani registráciu.","Kontrola vloženého textu v sekci „Je to podvod?“ probíhá jen ve vašem zařízení. Rozhovory se neukládají a po zavření zmizí.":"Kontrola vloženého textu v sekcii „Je to podvod?“ prebieha len vo vašom zariadení. Rozhovory sa neukladajú a po zatvorení zmiznú.","V zařízení si pamatujeme jen vaše nastavení (velikost písma, kontrast).":"V zariadení si pamätáme len vaše nastavenia (veľkosť písma, kontrast, jazyk).","Když otázka není v knihovně ověřených rad, odešle se (bez čísel karet, PINů a hesel) k zodpovězení umělé inteligenci Claude od firmy Anthropic. Taková odpověď je vždy označená „Informace mimo aplikaci“. Stejně tak se k rozboru odešle fotka zprávy, kterou nahrajete v sekci „Je to podvod?“. Nic z toho neukládáme.":"Keď otázka nie je v knižnici overených rád, odošle sa (bez čísel kariet, PIN-ov a hesiel) na zodpovedanie umelej inteligencii Claude od firmy Anthropic. Taká odpoveď je vždy označená „Informácia mimo aplikácie“. Rovnako sa na rozbor odošle fotka správy, ktorú nahráte v sekcii „Je to podvod?“. Nič z toho neukladáme.","Funkci „Mluvit“ zajišťuje váš prohlížeč (např. Google nebo Apple), který může hlas zpracovat na svém serveru.":"Funkciu „Hovoriť“ zabezpečuje váš prehliadač (napr. Google alebo Apple), ktorý môže hlas spracovať na svojom serveri.","Opravdu smazat nastavení a rozhovor? Aplikace se vrátí do výchozího stavu.":"Naozaj vymazať nastavenia a rozhovor? Aplikácia sa vráti do pôvodného stavu.","Vše jsem smazal.":"Všetko som vymazal.","Smazat vše z tohoto zařízení":"Vymazať všetko z tohto zariadenia","O aplikaci":"O aplikácii","DIGI parťák je trpělivý digitální průvodce pro seniory. Chatbot nejdřív hledá v knihovně předem připravených a zkontrolovaných rad s uvedenými zdroji. Teprve když tam odpověď není, odpoví pomocí umělé inteligence – takovou odpověď vždy výrazně označí jako neověřenou.":"DIGI parťák je trpezlivý digitálny sprievodca pre seniorov. Chatbot najprv hľadá v knižnici vopred pripravených a skontrolovaných rád s uvedenými zdrojmi. Až keď tam odpoveď nie je, odpovie pomocou umelej inteligencie – takú odpoveď vždy výrazne označí ako neoverenú.","Parťák nenahrazuje lékaře, banku, policii ani právníka. Ve vážné situaci volejte 112.":"Parťák nenahrádza lekára, banku, políciu ani právnika. V nebezpečnej situácii volajte 112.","Stav knihovny rad: {s}. Počet ověřených témat: {n}.":"Stav knižnice rád: {s}. Počet overených tém: {n}.","Změnit jazyk":"Zmeniť jazyk","Jazyk se nepodařilo načíst. Zkontrolujte internet.":"Jazyk sa nepodarilo načítať. Skontrolujte internet.","Jazyk změněn: {name}":"Jazyk zmenený: {name}","Vyberte jazyk aplikace. Ověřené rady jsou ve všech jazycích stejné.":"Vyberte jazyk aplikácie. Overené rady sú vo všetkých jazykoch rovnaké.","Rady se týkají života v Česku – telefonní čísla a instituce jsou české.":"Rady sa týkajú života v Česku – telefónne čísla a inštitúcie sú české.","Jste znovu připojeni k internetu.":"Ste opäť pripojení k internetu.","Jste offline. Parťák ale funguje dál.":"Ste offline. Parťák však funguje ďalej.","Běžné":"Bežné","Velké":"Veľké","Největší":"Najväčšie","Domů":"Domov","Vase zasilka nemohla byt dorucena. Pro opetovne doruceni uhradte poplatek 32 Kc ihned na www.posta-doruceni-cz.top":"Vasa zasielka nemohla byt dorucena. Pre opatovne dorucenie uhradte poplatok 32 Kc ihned na www.posta-dorucenie-cz.top","Pozor, jde o informaci mimo aplikaci. Není z ověřené knihovny DIGI parťáka, připravila ji umělá inteligence a může obsahovat chybu. Informaci si prosím ověřte.":"Pozor, ide o informáciu mimo aplikácie. Nie je z overenej knižnice DIGI parťáka, pripravila ju umelá inteligencia a môže obsahovať chybu. Informáciu si, prosím, overte.","Přeskočit na obsah":"Preskočiť na obsah","DIGI parťák – domů":"DIGI parťák – domov","Hlavní navigace":"Hlavná navigácia","Návody":"Návody","Změnit velikost písma":"Zmeniť veľkosť písma","Písmo":"Písmo","Pomoc":"Pomoc","Spodní navigace":"Spodná navigácia","Podvod?":"Podvod?","Obsahuje odkaz":"Obsahuje odkaz","Podvodníci posílají odkazy na falešné stránky, kde chtějí údaje z karty nebo hesla.":"Podvodníci posielajú odkazy na falošné stránky, kde chcú údaje z karty alebo heslá.","Zkrácený odkaz":"Skrátený odkaz","Zkrácený odkaz skrývá, kam vás ve skutečnosti zavede.":"Skrátený odkaz skrýva, kam vás v skutočnosti zavedie.","Chce údaje z karty, heslo nebo kód":"Chce údaje z karty, heslo alebo kód","Banka, pošta ani úřad po vás tyto údaje ve zprávě nikdy nechtějí.":"Banka, pošta ani úrad od vás tieto údaje v správe nikdy nechcú.","Tlačí vás do spěchu":"Tlačí vás do zhonu","Spěch a strach jsou hlavní zbraně podvodníků. Skutečné instituce vám dají čas.":"Zhon a strach sú hlavné zbrane podvodníkov. Skutočné inštitúcie vám dajú čas.","Chce, abyste něco zaplatili":"Chce, aby ste niečo zaplatili","Podvodníci často chtějí „poplatek“, doplatek nebo úhradu. Je to záminka, jak získat vaše peníze nebo údaje z karty.":"Podvodníci často chcú „poplatok“, doplatok alebo úhradu. Je to zámienka, ako získať vaše peniaze alebo údaje z karty.","Tváří se jako doručení balíku":"Tvári sa ako doručenie balíka","Falešné zprávy o balících jsou jedním z nejčastějších podvodů.":"Falošné správy o balíkoch sú jedným z najčastejších podvodov.","Vydává se za banku, úřad nebo firmu":"Vydáva sa za banku, úrad alebo firmu","Podvodníci se rádi vydávají za důvěryhodné instituce. Ověřte si to sami na oficiálním čísle.":"Podvodníci sa radi vydávajú za dôveryhodné inštitúcie. Overte si to sami na oficiálnom čísle.","Žádá převod peněz":"Žiada prevod peňazí","Žádný skutečný bankéř ani policista vás nežádá o převod na „bezpečný účet“.":"Žiadny skutočný bankár ani policajt vás nežiada o prevod na „bezpečný účet“.","Slibuje výhru nebo dárek":"Sľubuje výhru alebo darček","Pokud jste se soutěže neúčastnili, nemůžete nic vyhrát.":"Ak ste sa súťaže nezúčastnili, nemôžete nič vyhrať.","Vydává se za někoho z rodiny":"Vydáva sa za niekoho z rodiny","Častý trik „Ahoj mami, mám nové číslo“. Zavolejte blízkému na jeho staré číslo.":"Častý trik „Ahoj mami, mám nové číslo“. Zavolajte blízkemu na jeho staré číslo.","Žádá o peníze":"Žiada o peniaze","Kdykoli vás zpráva žádá o peníze, ověřte si odesílatele jinou cestou – nejlépe telefonátem na známé číslo.":"Kedykoľvek vás správa žiada o peniaze, overte si odosielateľa inou cestou – najlepšie telefonátom na známe číslo.","Chce, abyste si něco nainstalovali":"Chce, aby ste si niečo nainštalovali","Aplikace pro vzdálený přístup dávají podvodníkovi kontrolu nad vaším zařízením.":"Aplikácie na vzdialený prístup dávajú podvodníkovi kontrolu nad vaším zariadením.","Slibuje rychlý zisk":"Sľubuje rýchly zisk","Zaručené a vysoké výnosy neexistují. Je to typický investiční podvod.":"Zaručené a vysoké výnosy neexistujú. Je to typický investičný podvod.","Zahraniční telefonní číslo":"Zahraničné telefónne číslo","Zpráva přišla nebo odkazuje na číslo mimo Česko (předvolba jiná než +420).":"Správa prišla z čísla mimo Česka alebo naň odkazuje (predvoľba iná než +420).","Česká pošta":"Česká pošta","Policie ČR":"Polícia ČR (Policie ČR)","Česká bankovní asociace":"Česká bankovní asociace","NÚKIB – Národní úřad pro kybernetickou a informační bezpečnost":"NÚKIB – český Národný úrad pre kybernetickú a informačnú bezpečnosť","Česká národní banka":"Česká národná banka","Česká obchodní inspekce":"Česká obchodná inšpekcia","Nápověda Android (Google)":"Pomocník Android (Google)","Podpora Apple":"Podpora Apple","Nápověda WhatsApp":"Pomocník WhatsApp","Nápověda Facebooku":"Pomocník Facebooku","Nápověda Seznam.cz":"Pomocník Seznam.cz","Nápověda YouTube":"Pomocník YouTube","Manipulátoři.cz":"Manipulátoři.cz","Demagog.cz":"Demagog.cz","Úřad pro ochranu osobních údajů":"Úrad na ochranu osobných údajov (ČR)","IDOS – jízdní řády":"IDOS – cestovné poriadky","Mapy.com":"Mapy.com","SÚKL – eRecept":"SÚKL – eRecept","Portál občana":"Portál občana (ČR)","Integrovaný záchranný systém – tísňová čísla":"Integrovaný záchranný systém – tiesňové čísla","Život 90 – Senior telefon":"Život 90 – Senior telefon","Elpida – Linka seniorů":"Elpida – Linka seniorov","Nápověda Android (Google), Podpora Apple":"Pomocník Android (Google), Podpora Apple","Policie ČR, NÚKIB":"Polícia ČR, NÚKIB","Česká bankovní asociace, Policie ČR":"Česká bankovní asociace, Polícia ČR","SÚKL":"SÚKL","Koncept 11/2026 – před spuštěním nechat zkontrolovat odborníkem":"Koncept 11/2026 – pred spustením nechať skontrolovať odborníkom"},"kb":{"sms-balik":["Prišla mi SMS o balíku a mám doplatiť poplatok","Takéto správy sú veľmi často podvod. Podvodníci chcú, aby ste na odkaze zadali údaje z platobnej karty.",["Na odkaz v správe neklikajte a nič neplaťte.","Ak balík naozaj čakáte, overte si ho sami – na oficiálnom webe prepravcu alebo telefonicky na čísle z jeho webu.","Správu vymažte. Môžete ju aj nahlásiť ako spam.","Ak ste už na odkaz klikli a zadali kartu, hneď volajte svoju banku."],"Doručovacie firmy od vás nebudú chcieť údaje z karty cez odkaz v SMS."],"banka-vola":["Volá mi niekto z banky a chce previesť peniaze","Zložte. Banka vás nikdy nebude žiadať, aby ste previedli peniaze na „bezpečný účet“, ani od vás nebude chcieť PIN, heslo či kód z SMS.",["Hneď hovor ukončite. Nemusíte byť zdvorilí.","Nič neinštalujte a nikomu neoznamujte žiadne kódy.","Zavolajte sami do svojej banky – na číslo zo zadnej strany platobnej karty alebo z oficiálneho webu banky.","Ak ste už peniaze poslali alebo prezradili údaje, povedzte to banke hneď a volajte českú políciu na 158."],"Podvodníci vedia napodobniť aj skutočné číslo banky či polície. Na displeji môže byť „správne“ číslo – aj tak to môže byť podvod."],"uz-jsem-zadal":["Už som klikol/a na odkaz alebo zadal/a údaje z karty","Nebojte sa, dá sa konať. Čím skôr zavoláte do banky, tým väčšia je šanca peniaze zachrániť.",["Hneď zavolajte do svojej banky na číslo zo zadnej strany karty alebo z oficiálneho webu banky. Požiadajte o zablokovanie karty.","Ak ste niekomu dali prístup do telefónu alebo počítača, vypnite internet (Wi-Fi aj dáta).","Zmeňte heslo do internetového bankovníctva a e-mailu – ideálne s pomocou blízkeho človeka.","Podvod oznámte českej polícii na čísle 158.","Nehanbite sa. Podvodníci sú profesionáli a oklamú aj mladých a skúsených ľudí."],""],"falesny-policista":["Volá mi „policajt“ a chce, aby som mu dal/a peniaze","Skutočná polícia od vás nikdy nebude chcieť peniaze, hotovosť ani prevod na účet. Je to podvod.",["Zložte a nikomu nič neodovzdávajte.","Zavolajte sami na linku 158 a povedzte, čo sa stalo.","Ak niekto stojí pri dverách, neotvárajte a volajte 158."],""],"vnoucatko":["Píše mi „vnúča“ alebo „dcéra“ z nového čísla a chce peniaze","Toto je častý podvod. Než čokoľvek pošlete, overte si, že vám naozaj píše váš blízky.",["Neposielajte peniaze ani kódy.","Zavolajte svojmu blízkemu na jeho STARÉ, známe číslo alebo sa opýtajte iného člena rodiny.","Môžete položiť otázku, na ktorú pozná odpoveď len on (napr. meno vášho psa).","Ak sa ukáže, že to bol podvodník, číslo zablokujte."],""],"vzdalena-plocha":["Niekto chce, aby som si nainštaloval/a aplikáciu (AnyDesk, TeamViewer)","Nikdy neinštalujte aplikáciu na pokyn človeka, ktorý vám sám zavolal alebo napísal. Získal by tým prístup do vášho telefónu aj bankovníctva.",["Ukončite hovor alebo konverzáciu.","Nič neinštalujte. Ak ste už nainštalovali, vypnite internet a aplikáciu odinštalujte.","Zavolajte do banky na oficiálne číslo a povedzte, čo sa stalo."],"Banky, Microsoft ani operátori vám sami nevolajú kvôli „vírusom v počítači“."],"investice":["Ponúka mi niekto investíciu, kryptomeny alebo rýchly zisk","Sľub vysokého a „zaručeného“ zisku je typický znak podvodu. Často sa pri tom zneužívajú fotky známych osobností.",["Nikomu neposielajte peniaze ani doklady.","Neinštalujte žiadne aplikácie, ktoré vám „poradca“ odporučí.","Na webe Českej národnej banky si môžete overiť, či má firma povolenie.","O investíciách sa poraďte vo svojej banke osobne alebo s niekým blízkym."],"DIGI parťák nedáva investičné rady – pomôže vám len rozpoznať podvod."],"vyhra":["Vraj som niečo vyhral/a a mám zaplatiť poplatok","Ak ste sa súťaže nezúčastnili, nič ste nevyhrali. Skutočná výhra nikdy nevyžaduje poplatok ani údaje z karty.",["Neklikajte na odkaz a nič neplaťte.","Správu vymažte.","Ak ste zadali kartu, volajte banku."],""],"jak-poznat-podvod":["Ako spoznám podvodnú správu alebo e-mail?","Podvodné správy majú obvykle niekoľko spoločných znakov. Stačí si všimnúť jeden z nich a spozornieť.",["Zhon a strach: „ihneď“, „do 24 hodín“, „účet bude zablokovaný“.","Odkaz, na ktorom máte niečo vyplniť alebo zaplatiť.","Žiadosť o číslo karty, PIN, heslo alebo kód z SMS.","Neznámy odosielateľ, zahraničné číslo alebo čudná adresa.","Keď si nie ste istí, vložte správu do nástroja „Je to podvod?“ alebo sa opýtajte blízkeho."],""],"heslo":["Ako si vytvoriť bezpečné heslo?","Najlepšie je dlhé heslo zložené z niekoľkých slov, ktoré si ľahko zapamätáte, ale nikto iný ho neuhádne.",["Spojte 3–4 slová, ktoré spolu nesúvisia, napr. „Kos-Rozok-Zahrada-27“ (toto ale nepoužívajte, je verejné).","Pre každý účet použite iné heslo – hlavne pre e-mail a banku.","Heslá si môžete zapísať do zošita, ktorý zostane doma. Nikdy ich nefoťte ani neposielajte.","Kde sa dá, zapnite dvojfázové overenie (kód v SMS alebo v aplikácii)."],"Svoje heslo nikdy nikomu neoznamujte – ani banke, ani „technikovi“. Ani DIGI parťákovi."],"nakup-online":["Ako bezpečne nakupovať na internete?","Nakupujte v známych e-shopoch a pri neznámych si najprv overte, kto za nimi stojí.",["Adresu obchodu napíšte sami, neklikajte na odkazy z reklám a správ.","Pozrite sa na kontakt, IČO a adresu predajcu a na recenzie od iných ľudí.","Majte sa na pozore, keď je cena podozrivo nízka.","Pri neznámom predajcovi zvoľte platbu pri prevzatí.","Na bazároch nikdy neposielajte kód z SMS ani nevypĺňajte kartu cez odkaz od „kupujúceho“."],""],"laska-online":["Zoznámil/a som sa s niekým na internete a chce peniaze","Ak vás o peniaze žiada niekto, s kým ste sa nikdy osobne nestretli, je to s vysokou pravdepodobnosťou podvod.",["Neposielajte peniaze, darčeky ani kódy.","Porozprávajte sa o tom s niekým blízkym.","Ak ste už peniaze poslali, volajte banku a českú políciu (158)."],""],"pismo":["Ako zväčšiť písmo v telefóne?","Písmo si zväčšíte v Nastaveniach telefónu. Názvy položiek sa môžu podľa výrobcu trochu líšiť.",["Android: otvorte Nastavenia → Displej (alebo Dostupnosť) → Veľkosť písma.","iPhone: otvorte Nastavenia → Displej a jas → Veľkosť textu.","Posuňte jazdec doprava, kým sa vám text dobre nečíta.","Písmo v DIGI parťákovi zväčšíte tlačidlom „Písmo“ hore."],""],"whatsapp-fotka":["Ako poslať fotku cez WhatsApp?","Fotku pošlete v niekoľkých krokoch priamo z rozhovoru s daným človekom.",["Otvorte WhatsApp a ťuknite na meno človeka.","Dole ťuknite na ikonu spinky alebo „+“.","Vyberte „Galéria“ (Android) alebo „Fotky“ (iPhone).","Ťuknite na fotku a potom na zelenú šípku na odoslanie."],""],"whatsapp-video":["Ako zavolať videohovorom cez WhatsApp?","Videohovor začnete jedným ťuknutím v rozhovore s daným človekom.",["Otvorte WhatsApp a ťuknite na meno človeka.","Vpravo hore ťuknite na ikonu kamery.","Počkajte, kým to druhý človek prijme.","Hovor ukončíte červeným tlačidlom."],""],"wifi":["Ako sa pripojiť k Wi-Fi?","K domácej Wi-Fi sa pripojíte v Nastaveniach. Budete potrebovať názov siete a heslo – bývajú na štítku routera.",["Otvorte Nastavenia → Wi-Fi (na Androide niekedy Pripojenia → Wi-Fi).","Zapnite Wi-Fi, ak je vypnutá.","Ťuknite na názov svojej siete.","Zadajte heslo zo štítku na routeri a potvrďte."],"Na verejnej Wi-Fi (kaviareň, stanica) radšej nepoužívajte internetové bankovníctvo."],"aktualizace":["Mám aktualizovať telefón?","Áno, aktualizácie z Nastavení telefónu sú dôležité – opravujú bezpečnostné chyby.",["Aktualizáciu spúšťajte len z Nastavení telefónu alebo z obchodu Google Play / App Store.","Pred aktualizáciou telefón nabite a pripojte k Wi-Fi.","Ak vás k „aktualizácii“ vyzýva odkaz v SMS alebo e-maile, je to podvod."],""],"screenshot":["Ako urobiť snímku obrazovky (screenshot)?","Snímka obrazovky je „fotka“ toho, čo máte práve na displeji. Hodí sa napríklad na kontrolu podozrivej SMS v DIGI parťákovi.",["Android: stlačte súčasne tlačidlo zapnutia a tlačidlo na stlmenie hlasitosti (dolné) a hneď ich pustite.","iPhone bez tlačidla Plocha: stlačte súčasne bočné tlačidlo a tlačidlo na zvýšenie hlasitosti (horné).","iPhone s tlačidlom Plocha (okrúhle dole): stlačte súčasne tlačidlo Plocha a bočné (alebo horné) tlačidlo.","Obrazovka krátko blikne. Snímku nájdete v Galérii (Android) alebo vo Fotkách (iPhone)."],"Na niektorých telefónoch s Androidom sa kombinácia tlačidiel líši podľa výrobcu."],"plocha":["Ako si dať DIGI parťáka na plochu telefónu?","DIGI parťáka si môžete pridať na plochu ako bežnú aplikáciu. Potom ho otvoríte jedným ťuknutím.",["Android (Chrome): ťuknite vpravo hore na tri bodky → „Pridať na plochu“ alebo „Inštalovať aplikáciu“.","iPhone (Safari): ťuknite dole na ikonu Zdieľať (štvorček so šípkou) → „Pridať na plochu“.","Potvrďte tlačidlom „Pridať“."],""],"facebook":["Čo je Facebook a ako ho začať používať?","Facebook je sociálna sieť – miesto na internete, kde si ľudia zdieľajú fotky a novinky a posielajú si správy (cez aplikáciu Messenger). Používanie je zadarmo.",["Stiahnite si aplikáciu Facebook z obchodu Google Play (Android) alebo App Store (iPhone), alebo napíšte do prehliadača sami facebook.com.","Nový účet: ťuknite na „Vytvoriť nový účet“ a vyplňte meno, dátum narodenia a svoj e-mail alebo telefón. Zvoľte heslo.","Prihlásenie: zadajte e-mail alebo telefón a heslo a ťuknite na „Prihlásiť sa“.","V nastaveniach súkromia zvoľte, že vaše príspevky vidia len „Priatelia“.","Žiadosti o priateľstvo prijímajte len od ľudí, ktorých naozaj poznáte."],"Na Facebooku sa vyskytujú falošné profily a reklamy na „zaručené zárobky“ so známymi osobnosťami. Keď vás niekto žiada o peniaze, overte si to telefonátom."],"whatsapp-zacit":["Čo je WhatsApp a ako si ho nainštalovať?","WhatsApp je aplikácia na správy, fotky a hovory (aj s obrazom) cez internet. Na Wi-Fi je zadarmo aj do zahraničia. Používa vaše telefónne číslo.",["Otvorte Obchod Google Play (Android) alebo App Store (iPhone) a vyhľadajte „WhatsApp Messenger“.","Skontrolujte, že vývojár je „WhatsApp LLC“, a ťuknite na Inštalovať (Získať).","Otvorte WhatsApp, odsúhlaste podmienky a zadajte svoje telefónne číslo.","Príde vám SMS s kódom – zadajte ho len priamo do WhatsAppu.","Napíšte svoje meno. Vaše kontakty, ktoré WhatsApp majú, sa objavia samy."],"Overovací kód z WhatsAppu nikdy nikomu neposielajte – ani „kamarátovi“, ktorý oň píše. Takto podvodníci kradnú účty."],"email":["Ako si založiť e-mail a poslať správu s prílohou?","E-mail je elektronická pošta. V Česku sú najpoužívanejšie e-mail na Seznam.cz a Gmail od Googlu. Oboje je zadarmo.",["Založenie: na webe seznam.cz ťuknite na „E-mail“ a „Zaregistrovat se“, alebo si založte účet Google (Gmail) – na Androide ho obvykle už máte.","Vymyslite si adresu (napr. jana.novakova@seznam.cz) a bezpečné heslo. Oboje si zapíšte.","Odoslanie: ťuknite na „Napísať“, do poľa „Komu“ zadajte adresu, napíšte predmet a text.","Príloha (fotka): ťuknite na ikonu spinky a vyberte fotku.","Ťuknite na „Odoslať“ (šípka)."],"E-maily, ktoré chcú heslo, platbu alebo kliknutie na odkaz, bývajú podvod. Keď si nie ste istí, vložte ich do „Je to podvod?“."],"youtube":["Čo je YouTube a ako na ňom hľadať videá?","YouTube je web a aplikácia s videami – pesničky, relácie, recepty, návody. Je zadarmo, len sa občas prehrá reklama.",["Otvorte aplikáciu YouTube (býva v telefóne predinštalovaná) alebo napíšte do prehliadača youtube.com.","Ťuknite na lupu hore a napíšte, čo hľadáte (napr. „Karel Gott“ alebo „bryndzové halušky recept“).","Ťuknite na video. Reklamu môžete po pár sekundách preskočiť tlačidlom „Preskočiť“.","Video zväčšíte na celú obrazovku otočením telefónu na šírku."],"Reklamy na rýchle zbohatnutie alebo zázračné lieky sú často podvod, aj keď v nich vystupujú známe osobnosti."],"aplikace-instalace":["Ako bezpečne nainštalovať aplikáciu?","Aplikácie sťahujte len z oficiálneho obchodu: Google Play na Androide, App Store na iPhone. Väčšina aplikácií je zadarmo.",["Otvorte Obchod Google Play (farebný trojuholník) alebo App Store (modré „A“).","Hore ťuknite na vyhľadávanie a napíšte názov aplikácie.","Skontrolujte meno vývojára (napr. pri bankovej aplikácii vaša banka) a hodnotenie.","Ťuknite na „Inštalovať“ (Android) alebo „Získať“ (iPhone) a počkajte.","Odinštalovanie: podržte prst na ikone aplikácie a zvoľte „Odinštalovať“ / „Odstrániť aplikáciu“."],"Nikdy neinštalujte aplikáciu podľa pokynov neznámeho volajúceho alebo z odkazu v SMS."],"zapomenute-heslo":["Zabudol/a som heslo – čo teraz?","Zabudnuté heslo sa dá takmer vždy obnoviť. Služba vám pošle kód na telefón alebo do e-mailu a vy si nastavíte nové heslo.",["Na prihlasovacej stránke ťuknite na „Zabudnuté heslo?“.","Zadajte svoj e-mail alebo telefón. Príde vám SMS alebo e-mail s kódom či odkazom.","Kód zadajte len na tej stránke, kde ste obnovu sami začali.","Vymyslite nové heslo a zapíšte si ho do zošita, ktorý zostane doma.","Pri internetovom bankovníctve volajte svoju banku na číslo zo zadnej strany karty."],"Keď vám príde kód na obnovu hesla, o ktorý ste nežiadali, nikomu ho neposielajte – niekto sa možno snaží dostať do vášho účtu."],"baterie":["Telefón sa rýchlo vybíja – čo s tým?","Najviac energie spotrebuje jasný displej, navigácia, videá a aplikácie bežiace na pozadí. Pár úprav výdrž výrazne predĺži.",["Znížte jas displeja (stiahnite lištu zhora a posuňte jazdec so slniečkom).","Zapnite úsporný režim: Android – Nastavenia → Batéria → Úspora energie; iPhone – Nastavenia → Batéria → Režim nízkej spotreby.","Zatvorte aplikácie, ktoré nepoužívate, a vypnite polohu (GPS), keď ju nepotrebujete.","Nabíjajte originálnou alebo kvalitnou nabíjačkou. Nemusíte čakať, kým sa telefón úplne vybije.","Ak je telefón starý niekoľko rokov a vybíja sa aj tak rýchlo, môže pomôcť výmena batérie v servise."],""],"pamet":["Telefón hlási plnú pamäť – ako uvoľniť miesto?","Miesto v telefóne najčastejšie zaberajú videá, fotky a súbory z WhatsAppu. Než ich vymažete, zálohujte si ich.",["Pozrite sa, čo zaberá miesto: Android – Nastavenia → Úložisko (alebo Starostlivosť o zariadenie); iPhone – Nastavenia → Všeobecné → Úložisko iPhonu.","Zálohujte fotky (Google Fotky alebo iCloud) a potom vymažte veľké videá.","Vo WhatsAppe: Nastavenia → Úložisko a dáta → Spravovať úložisko – vymažte veľké súbory a preposlané videá.","Odinštalujte aplikácie, ktoré nepoužívate.","Na konci vysypte kôš vo Fotkách („Nedávno vymazané“)."],""],"pomaly-telefon":["Telefón je pomalý alebo zamŕza","Najčastejšie pomôže obyčajný reštart. Telefón si tým „upratá“ pamäť.",["Reštartujte telefón: podržte tlačidlo zapnutia a zvoľte „Reštartovať“ (na iPhone vypnúť a znova zapnúť).","Ak telefón vôbec nereaguje, podržte tlačidlo zapnutia dlhšie (asi 10–15 sekúnd).","Nainštalujte aktualizácie systému a aplikácií.","Uvoľnite miesto v pamäti – plná pamäť telefón spomaľuje.","Keď nič nepomôže, poraďte sa v predajni alebo servise vášho operátora."],""],"hlasitost":["Nepočujem zvonenie – ako zosilniť telefón?","Hlasitosť zvonenia nastavíte tlačidlami na boku telefónu alebo v Nastaveniach. Skontrolujte aj, či telefón nie je v tichom režime.",["Stlačte horné tlačidlo hlasitosti na boku telefónu, keď nehrá žiadne video.","Android: Nastavenia → Zvuky a vibrácie → Hlasitosť → posuňte „Tón zvonenia“ doprava.","iPhone: Nastavenia → Zvuky a haptika → posuňte jazdec „Zvonenie a upozornenia“. Na boku skontrolujte prepínač tichého režimu (oranžová farba = ticho).","Vypnite režim „Nerušiť“ (ikona mesiaca v hornej lište).","Zapnite aj vibrácie, aby ste zvonenie ucítili vo vrecku."],""],"blokovani":["Ako zablokovať otravné číslo?","Číslo, ktoré vás obťažuje, môžete v telefóne zablokovať. Potom vám z neho nikto nezavolá ani nenapíše.",["Android: otvorte aplikáciu Telefón → Nedávne, podržte prst na čísle a zvoľte „Blokovať“ (prípadne „Nahlásiť spam“).","iPhone: otvorte Telefón → Nedávne, ťuknite na „i“ vedľa čísla a potom na „Blokovať volajúceho“.","Pri SMS: otvorte správu, ťuknite na číslo hore a zvoľte Blokovať.","Neznáme čísla nemusíte dvíhať. Kto vás potrebuje, nechá odkaz alebo napíše."],"Ak volajúci tvrdí, že je z banky alebo polície, zložte a zavolajte sami na oficiálne číslo."],"kontakt":["Ako si uložiť telefónne číslo do kontaktov?","Číslo uložíte jednoducho z aplikácie Telefón alebo Kontakty. Potom pri hovore uvidíte meno namiesto čísla.",["Otvorte aplikáciu Telefón → Nedávne a ťuknite na číslo, ktoré chcete uložiť.","Zvoľte „Vytvoriť nový kontakt“ alebo „Pridať kontakt“ (na iPhone „i“ → Vytvoriť nový kontakt).","Napíšte meno a priezvisko, prípadne pridajte fotku.","Ťuknite na „Uložiť“ (Hotovo).","Nové číslo môžete pridať aj v aplikácii Kontakty tlačidlom „+“."],""],"nouzove-info":["Ako si do telefónu nastaviť zdravotné údaje a núdzový kontakt?","Do telefónu si môžete uložiť zdravotné údaje a núdzový kontakt. Záchranári ich uvidia aj na zamknutom telefóne.",["iPhone: otvorte aplikáciu Zdravie → vaša fotka vpravo hore → Zdravotný preukaz → Upraviť. Vyplňte údaje a zapnite „Zobraziť pri zamknutí“.","Android: Nastavenia → Bezpečnosť a núdzové situácie (alebo Núdzové informácie). Presný názov sa líši podľa výrobcu.","Pridajte núdzový kontakt – niekoho blízkeho.","Uveďte dôležité choroby, alergie a lieky, ktoré beriete."],""],"ztraceny-telefon":["Stratil/a som telefón – ako ho nájsť?","Telefón môžete nájsť, zamknúť alebo na diaľku rozozvučať z počítača alebo z telefónu niekoho blízkeho.",["Android: na inom zariadení otvorte stránku android.com/find a prihláste sa svojím účtom Google.","iPhone: otvorte stránku icloud.com/find a prihláste sa svojím Apple ID (alebo použite aplikáciu Nájsť na inom zariadení Apple).","Telefón môžete rozozvučať, zobraziť na mape alebo zamknúť.","Pri krádeži volajte svojho operátora (zablokovanie SIM), banku (ak máte v telefóne bankovníctvo) a českú políciu na 158."],""],"zaloha-fotek":["Ako si zálohovať fotky, aby som o ne neprišiel/a?","Zálohované fotky sa automaticky ukladajú aj mimo telefónu. Keď telefón stratíte alebo rozbijete, fotky vám zostanú.",["Android: otvorte aplikáciu Google Fotky → vaša ikona vpravo hore → zapnite „Zálohovanie“.","iPhone: Nastavenia → vaše meno hore → iCloud → Fotky → zapnite „Synchronizovať tento iPhone“.","Zálohovanie prebieha najlepšie na Wi-Fi a pri nabíjaní.","Zadarmo je len obmedzené miesto. Keď dôjde, služba ponúkne platené rozšírenie – nemusíte ho kupovať, môžete vymazať nepotrebné."],""],"mobilni-data":["Čo sú mobilné dáta a kedy ich zapnúť?","Mobilné dáta sú internet od vášho operátora. Fungujú aj vonku, kde nie je Wi-Fi. Koľko dát máte, záleží od tarifu.",["Zapnutie: stiahnite prstom lištu z horného okraja a ťuknite na ikonu „Mobilné dáta“ (dve šípky).","Doma a u blízkych používajte radšej Wi-Fi – nespotrebúva vaše dáta.","V zahraničí mimo EÚ vypnite dáta alebo roaming, aby vám neprišiel vysoký účet. V EÚ platíte ako doma.","Koľko dát vám zostáva, zistíte v aplikácii svojho operátora."],""],"qr-kod":["Ako naskenovať QR kód?","QR kód je štvorček z bodiek, ktorý obsahuje odkaz alebo platobné údaje. Prečítate ho fotoaparátom telefónu.",["Otvorte Fotoaparát a namierte ho na QR kód (nič nefoťte).","Objaví sa odkaz – ťuknite naň.","QR platba (napr. na faktúre či zloženke): otvorte aplikáciu svojej banky a zvoľte „Platba QR kódom“. Údaje sa vyplnia samy, skontrolujte sumu a príjemcu."],"QR kódy v e-mailoch, SMS alebo nalepené na parkovacích automatoch môžu viesť na podvodné stránky. Platby robte len v aplikácii svojej banky."],"pin-karty":["Ako si zmeniť PIN ku karte?","PIN ku karte si zmeníte v aplikácii svojej banky, v internetovom bankovníctve, na pobočke alebo pri niektorých bankomatoch vašej banky.",["Otvorte aplikáciu svojej banky a hľadajte pri karte „Zmeniť PIN“ alebo „Zobraziť PIN“.","Bez aplikácie zájdite na pobočku banky s občianskym preukazom.","Nový PIN voľte tak, aby nebol dátum narodenia ani 1234.","PIN si nepíšte ku karte ani do telefónu."],"Banka od vás PIN nikdy nechce – ani telefonicky, ani v SMS, ani e-mailom. Kto oň žiada, je podvodník."],"internetove-bankovnictvi":["Ako začať s internetovým bankovníctvom bezpečne?","Internetové bankovníctvo vám zriadi vaša banka – najistejšie osobne na pobočke, kde vám rovno pomôžu s nastavením.",["Zájdite na pobočku a požiadajte o internetové a mobilné bankovníctvo. Povedzte, že s tým začínate.","Aplikáciu banky si stiahnite len z Google Play alebo App Store (vydavateľom musí byť vaša banka).","Do bankovníctva sa prihlasujte len cez túto aplikáciu alebo adresu, ktorú napíšete sami. Nikdy cez odkaz zo správy.","Platbu faktúry urobte cez „Platba QR kódom“ alebo „Nová platba“. Pred potvrdením skontrolujte číslo účtu a sumu."],"Prihlasovacie údaje a potvrdzovacie kódy nikomu neoznamujte. Banka vás nikdy nevyzve na prevod na „bezpečný účet“."],"platba-telefonem":["Ako platiť telefónom namiesto kartou?","Platobnú kartu si môžete nahrať do telefónu a platiť priložením telefónu k terminálu, rovnako ako kartou.",["Otvorte aplikáciu svojej banky a hľadajte pri karte „Pridať do Google Wallet“ alebo „Pridať do Apple Wallet“.","Potvrďte pridanie podľa pokynov banky.","Pri platení odomknite telefón a priložte ho k terminálu.","Telefón majte zamknutý kódom alebo odtlačkom prsta."],""],"hoax":["Ako spoznať hoax a falošnú správu?","Hoax je poplašná alebo vymyslená správa, ktorá sa šíri preposielaním. Často straší, rozčuľuje alebo sľubuje zázraky.",["Spozornite, keď správa vyzýva „pošli ďalej všetkým“ alebo veľmi straší a pobúri.","Hľadajte zdroj: kto to napísal a kde to vyšlo? Seriózne správy majú autora a dátum.","Overte si to v dôveryhodnom médiu alebo na weboch na overovanie faktov (v Česku Manipulátoři.cz a Demagog.cz).","Keď si nie ste istí, správu nepreposielajte."],""],"cookies":["Čo mám robiť s lištou „cookies“ na webe?","Cookies sú malé súbory, ktorými si web pamätá, čo robíte. Lišta sa pýta, či smie sledovať vaše správanie kvôli reklame.",["Pokojne zvoľte „Odmietnuť všetko“ alebo „Len nevyhnutné“. Web bude fungovať ďalej.","Ak také tlačidlo nevidíte, ťuknite na „Nastavenia“ a nechajte zapnuté len „Nevyhnutné“.","Lištu nemusíte riešiť zakaždým – web si vašu voľbu zapamätá."],""],"vir-hlaska":["Na webe vyskočilo, že mám v telefóne vírus","Hlášky na webových stránkach typu „Váš telefón je zavírený!“ sú takmer vždy podvod. Chcú vás vystrašiť, aby ste niečo nainštalovali alebo zaplatili.",["Na nič v okne neklikajte a nevolajte na číslo, ktoré sa zobrazí.","Zatvorte kartu alebo celý prehliadač. Prípadne telefón reštartujte.","Nič neinštalujte a nič neplaťte.","Ak ste už niečo nainštalovali alebo zadali kartu, volajte banku a požiadajte o pomoc blízkeho."],""],"mapy":["Ako nájsť cestu a spojenie v telefóne?","Cestu aj spojenie nájdete v aplikáciách Mapy.com (predtým Mapy.cz) alebo Google Mapy. České cestovné poriadky sú na webe IDOS.",["Otvorte Mapy.com alebo Google Mapy a do vyhľadávania napíšte, kam chcete ísť.","Ťuknite na „Trasa“ a zvoľte, či idete pešo, autom alebo hromadnou dopravou.","Spojenie autobusom a vlakom nájdete na webe idos.cz – zadajte odkiaľ, kam a kedy.","Lístok na vlak si kúpite v aplikácii Můj vlak (České dráhy) alebo pri pokladni. Na zľavy pre seniorov sa opýtajte pri pokladni."],""],"objednat-lekar":["Ako sa objednať k lekárovi cez internet?","Mnohé ambulancie ponúkajú objednanie cez internet alebo e-mail. Každá však používa iný systém, preto sa najprv opýtajte v ambulancii.",["Opýtajte sa sestričky, či sa môžete objednávať online a na akej adrese.","Adresu alebo aplikáciu si nechajte napísať na papier a do prehliadača ju píšte sami.","Vyberte termín a potvrďte ho. Obvykle vám príde potvrdenie e-mailom alebo SMS.","Keď vám online objednanie nevyhovuje, telefonát do ambulancie je stále v poriadku."],"Na otázky o zdraví a liekoch vám odpovie lekár alebo lekárnik."],"erecept":["Ako funguje eRecept?","eRecept je elektronický recept. Lekár vám ho pošle v SMS alebo e-mailom, prípadne vytlačí.",["Počkajte na SMS alebo e-mail od lekára s kódom receptu.","V lekárni ukážte správu s kódom (alebo vytlačený papier).","Lekárnik kód načíta a vydá vám liek.","Kód môžete poslať aj blízkemu, ktorý liek vyzdvihne za vás."],"Na otázky o liekoch, dávkovaní a zdraví odpovedá lekár alebo lekárnik, nie DIGI parťák."],"identita":["Ako vybaviť veci s českými úradmi cez internet?","Mnoho vecí s českými úradmi vybavíte na Portáli občana (Portál občana). Prihlásite sa napríklad bankovou identitou – rovnako ako do internetového bankovníctva.",["Adresu Portálu občana napíšte do prehliadača sami: obcan.portal.gov.cz.","Zvoľte prihlásenie cez svoju banku (banková identita) alebo inú ponúkanú možnosť.","Ak si nie ste istí, požiadajte o pomoc blízkeho alebo pracovníka Czech POINTu na pošte či úrade."],"Odkazy na „úrad“ v SMS alebo e-maile nepoužívajte – adresu vždy píšte sami."],"cisla":["Aké sú dôležité telefónne čísla?","Tu sú najdôležitejšie čísla. Na každé môžete ťuknúť a rovno zavolať.",[],""],"samota":["Je mi smutno a cítim sa sám/sama","To ma mrzí. Takéto pocity sú úplne v poriadku a nemusíte na ne byť sami. Na týchto bezplatných linkách vás radi vypočujú (po česky).",[],""],"krize":["Je mi naozaj zle a neviem si rady","Veľmi ma mrzí, že sa takto cítite. Prosím, porozprávajte sa s niekým hneď teraz. Ste dôležití.",["Zavolajte na Linku prvej psychickej pomoci 116 123 – bezplatne a nonstop.","Ak ste v ohrození, volajte 112 alebo 155.","Môžete zavolať aj niekomu blízkemu a požiadať ho, aby prišiel."],""],"zdravi-nouze":["Zdravotné ťažkosti – volajte pomoc","Toto môže byť vážne. Prosím, hneď volajte záchrannú službu 155 alebo tiesňovú linku 112.",["Zavolajte 155 alebo 112.","Povedzte, kde ste a čo sa deje.","Ak je to možné, odomknite dvere a zavolajte suseda alebo blízkeho."],""],"mimo-zdravi":["Otázky o zdraví a liekoch","Na otázky o zdraví a liekoch vám bezpečne odpovie len lekár alebo lekárnik. Nechcem vám dať nepresnú radu.",["Zavolajte svojmu praktickému lekárovi.","Opýtajte sa v lekárni – lekárnici radi poradia zadarmo.","Pri náhlych ťažkostiach volajte 155."],""],"mimo-finance":["Finančné a právne rady","Finančné a právne rady neposkytujem – mohol by som vám nechtiac uškodiť. Obráťte sa, prosím, na odborníka.",["O peniazoch sa poraďte osobne vo svojej banke.","S právnymi otázkami pomáhajú bezplatné poradne, napr. cez Senior telefon.","Ak vás niekto na zmluvu tlačí a ponáhľa, nič nepodpisujte."],""],"pozdrav":["Pozdrav","Dobrý deň, rád vás vidím! Som DIGI parťák. Pomôžem vám s telefónom, internetom a bezpečnosťou online. Na čo sa chcete opýtať?",[],""],"dekuji":["Poďakovanie","Rado sa stalo! Kedykoľvek budete chcieť, som tu. Žiadna otázka nie je hlúpa.",[],""],"kdo-jsi":["Kto je DIGI parťák?","Som DIGI parťák – digitálny pomocník, nie človek. Najprv odpovedám z knižnice overených rád. Keď tam odpoveď nie je, skúsim poradiť pomocou umelej inteligencie a vždy vás upozorním, že si to máte overiť.",["Viem poradiť s telefónom a aplikáciami.","Pomôžem rozpoznať podvodné správy a hovory.","Ukážem vám, kam zavolať o pomoc."],""]},"guides":{"pismo":["Zväčšiť písmo v telefóne","Väčšie písmo sa lepšie číta a šetrí oči. Nič sa tým nepokazí – kedykoľvek to môžete vrátiť.",[["Otvorte Nastavenia","Nájdite na ploche ikonu ozubeného kolieska s nápisom „Nastavenia“ a ťuknite na ňu. ||"],["Nájdite položku displeja","Android: ťuknite na „Displej“ (pri niektorých telefónoch „Dostupnosť“). iPhone: ťuknite na „Displej a jas“.","Položky môžete hľadať aj lupou hore – napíšte „písmo“."],["Ťuknite na Veľkosť písma","Android: „Veľkosť písma“ alebo „Veľkosť a štýl písma“. iPhone: „Veľkosť textu“. ||"],["Posuňte jazdec doprava","Čím viac doprava, tým väčšie písmo. Ukážkový text sa hneď mení, takže uvidíte výsledok. ||"],["Hotovo","Vráťte sa tlačidlom Späť alebo zatvorte Nastavenia. Písmo zostane väčšie všade v telefóne. ||"]]],"whatsapp-fotka":["Poslať fotku cez WhatsApp","Urobte radosť rodine. Fotku pošlete priamo z rozhovoru s daným človekom.",[["Otvorte WhatsApp","Ťuknite na zelenú ikonu s bielym telefónom v bubline. ||"],["Vyberte človeka","V zozname rozhovorov ťuknite na meno toho, komu chcete fotku poslať. ||"],["Ťuknite na spinku alebo +","Ikona je dole vedľa políčka na písanie. Na Androide je to spinka, na iPhone znamienko plus. ||"],["Vyberte fotku","Ťuknite na „Galéria“ (Android) alebo „Knižnica fotiek“ (iPhone) a potom na fotku, ktorú chcete poslať. ||"],["Odošlite","Ťuknite na okrúhle zelené tlačidlo so šípkou. Fotka je na ceste!","Dve modré fajky znamenajú, že si ju druhý človek už pozrel."]]],"whatsapp-video":["Videohovor cez WhatsApp","Uvidíte sa s blízkymi, aj keď sú ďaleko. Hovor cez Wi-Fi nič nestojí.",[["Otvorte WhatsApp","Ťuknite na zelenú ikonu WhatsApp. ||"],["Vyberte človeka","Ťuknite na meno toho, komu chcete zavolať. ||"],["Ťuknite na kameru","Vpravo hore je ikona malej kamery. Ťuknite na ňu.","Ikona slúchadla vedľa je obyčajný hovor bez obrazu."],["Počkajte na prijatie","Keď druhý človek hovor prijme, uvidíte sa. Telefón držte pred tvárou. ||"],["Ukončite hovor","Ťuknite na červené tlačidlo so slúchadlom. ||"]]],"podvodna-sms":["Čo robiť s podozrivou SMS","Podvodné správy chodia každému. Dôležité je vedieť, ako sa zachovať.",[["Neponáhľajte sa","Podvodníci chcú, aby ste konali hneď. Vy máte čas. Zhlboka sa nadýchnite. ||"],["Neklikajte na odkaz","Na odkaz v správe neťukajte a na správu neodpovedajte. ||"],["Overte si to inak","Ak správa tvrdí, že je od banky, pošty alebo úradu, zavolajte im sami na číslo z ich oficiálneho webu alebo z karty. ||"],["Vymažte správu","Podržte prst na správe a vyberte „Vymazať“. Číslo môžete zablokovať. ||"],["Už ste klikli?","Nič sa nedeje, ak ste nič nevyplnili. Ak ste zadali kartu alebo heslo, hneď volajte svoju banku.","Správu môžete skontrolovať v DIGI parťákovi v sekcii „Je to podvod?“."]]],"screenshot-android":["Snímka obrazovky na Androide","Snímka obrazovky (screenshot) je fotka toho, čo máte práve na displeji. Hodí sa napríklad na kontrolu podozrivej správy.",[["Otvorte, čo chcete odfotiť","Napríklad podozrivú SMS. Správu otvorte tak, aby bol vidieť celý text aj odosielateľ. ||"],["Nájdite dve tlačidlá","Na boku telefónu je tlačidlo zapnutia a tlačidlo hlasitosti. Budete potrebovať zapnutie a dolnú časť hlasitosti (stlmenie). ||"],["Stlačte obe naraz","Stlačte súčasne tlačidlo zapnutia a stlmenia hlasitosti. Držte ich len chvíľku (asi 1 sekundu) a pustite.","Keď sa namiesto toho objaví ponuka vypnutia, pustili ste tlačidlá neskoro. Skúste to znova a rýchlejšie."],["Obrazovka blikne","Budete počuť zvuk alebo uvidíte krátke bliknutie a dole malý náhľad. Snímka je uložená. ||"],["Kde snímku nájdete","Otvorte aplikáciu Galéria alebo Fotky (Google). Snímka je medzi najnovšími fotkami, často v priečinku „Snímky obrazovky“. ||"],["Nejde to?","Pri niektorých telefónoch (napr. Samsung) sa dá snímka urobiť aj takto: stiahnite prstom lištu z horného okraja nadol a ťuknite na „Snímka obrazovky“. Postup sa líši podľa výrobcu.","Snímku môžete nahrať v DIGI parťákovi v sekcii „Je to podvod?“."]]],"screenshot-iphone":["Snímka obrazovky na iPhone","Snímka obrazovky (screenshot) je fotka toho, čo máte práve na displeji. Postup závisí od toho, či má váš iPhone okrúhle tlačidlo Plocha dole pod displejom.",[["Otvorte, čo chcete odfotiť","Napríklad podozrivú SMS. Správu otvorte tak, aby bol vidieť celý text aj odosielateľ. ||"],["iPhone BEZ tlačidla Plocha","Novšie iPhony (displej až po okraj): stlačte súčasne bočné tlačidlo vpravo a tlačidlo na zvýšenie hlasitosti vľavo (horné). Hneď ich pustite. ||"],["iPhone S tlačidlom Plocha","Staršie iPhony a iPhone SE (okrúhle tlačidlo dole): stlačte súčasne tlačidlo Plocha a bočné tlačidlo vpravo (pri najstarších modeloch tlačidlo hore). ||"],["Obrazovka blikne","Obrazovka krátko zbelie a vľavo dole sa objaví malý náhľad. Nemusíte naň ťukať – snímka sa uloží sama.","Keď sa namiesto toho objaví posúvač „Vypnúť“, držali ste tlačidlá príliš dlho. Ťuknite na Zrušiť a skúste to rýchlejšie."],["Kde snímku nájdete","Otvorte aplikáciu Fotky. Snímka je medzi najnovšími fotkami a tiež v albume „Snímky obrazovky“.","Snímku môžete nahrať v DIGI parťákovi v sekcii „Je to podvod?“."]]],"banka-hovor":["Volá mi „banka“ – čo teraz?","Najčastejší podvod na seniorov. Stačí si zapamätať jedno pravidlo: zložiť a zavolať sám.",[["Zložte","Keď vám niekto z „banky“ alebo „polície“ volá kvôli peniazom, ukončite hovor. Nemusíte sa ospravedlňovať. ||"],["Nič neprezrádzajte","Nikomu nehovorte PIN, heslá ani kódy z SMS. Banka ich od vás nikdy nebude chcieť. ||"],["Zavolajte sami","Vezmite platobnú kartu a zavolajte na číslo, ktoré je na jej zadnej strane. ||"],["Povedzte, čo sa stalo","Pracovník banky vám povie, či je váš účet v poriadku. ||"]]],"erecept":["Vyzdvihnúť eRecept","Recept už nemusí byť na papieri. Stačí kód, ktorý vám pošle lekár.",[["Počkajte na správu","Lekár vám pošle SMS alebo e-mail s kódom receptu. Môže vám ho aj vytlačiť. ||"],["Zájdite do lekárne","Môžete ísť do ktorejkoľvek lekárne. ||"],["Ukážte kód","Otvorte správu od lekára a ukážte ju lekárnikovi, alebo mu kód nadiktujte. ||"],["Hotovo","Lekárnik kód načíta a vydá vám liek.","Kód môžete preposlať blízkemu, ktorý liek vyzdvihne za vás."]]],"plocha":["DIGI parťák na ploche telefónu","Pridajte si parťáka na plochu ako aplikáciu. Potom ho otvoríte jedným ťuknutím.",[["Otvorte DIGI parťáka v prehliadači","Android: v Chrome. iPhone: v Safari. ||"],["Otvorte ponuku","Android: ťuknite vpravo hore na tri bodky. iPhone: ťuknite dole na ikonu Zdieľať (štvorček so šípkou nahor). ||"],["Pridať na plochu","Vyberte „Pridať na plochu“ alebo „Inštalovať aplikáciu“. ||"],["Potvrďte","Ťuknite na „Pridať“. Na ploche sa objaví ikona s usmievavou bublinou. ||"]]]},"phones":{"112":["Tiesňová linka","Akékoľvek ohrozenie života, zdravia alebo majetku. Funguje aj bez kreditu."],"150":["Hasiči","Požiar, únik plynu, technická pomoc."],"155":["Záchranná služba","Náhle zdravotné ťažkosti, úraz, bezvedomie."],"158":["Česká polícia","Podvod, krádež, vyhrážky, podozrivý človek pri dverách."],"senior":["Senior telefon (Život 90)","Bezplatná linka pre seniorov a ich blízkych. Nonstop, po česky."],"elpida":["Linka seniorov (Elpida)","Bezplatný rozhovor, keď je vám smutno alebo potrebujete poradiť. Po česky."],"psych":["Linka prvej psychickej pomoci","Keď je toho na vás veľa. Bezplatne, nonstop, po česky."]},"cats":{"bezpeci":"Bezpečnosť online","telefon":"Telefón a aplikácie","internet":"Internet, správy a siete","penize":"Banka a platenie","urady":"Úrady a lekár","pomoc":"Pomoc a podpora"},"urgent":{"krize":["nechcem žiť","nechcem uz zit","zabiť sa","samovražd","ublížiť si","nemá to zmysel"],"zdravi-nouze":["bolesť na hrudi","bolí ma na hrudi","nemôžem dýchať","nemozem dychat","infarkt","mŕtvica","porážka","bezvedomie","odpadol","spadol a nemôže vstať","krváca"],"uz-jsem-zadal":["zadal som kartu","zadala som kartu","klikol som na odkaz","klikla som na odkaz","poslal som peniaze","poslala som peniaze","okradli ma","ukradli mi peniaze"],"banka-vola":["bezpečný účet","volá mi banka","bezpečnostné oddelenie banky","previesť peniaze"]},"scam":{"card":"číslo karty|údaje z karty|údaje karty|cvv|pin|heslo|prihlasovacie|overovací kód|sms kód|kód z sms","urgent":"ihneď|okamžite|bezodkladne|do 24|do 48|posledná výzva|posledné upozornenie|dnes do|vyprší|prepadne|zablokovan|pozastaven|zrušen|deaktiv","fee":"poplatok|doplatok|clo|dobierk|uhraďte|zaplaťte|úhrad","parcel":"zásielk|balík|doruč|kuriér|pošta|slovenská pošta|packeta","bank":"bank|účet|polícia|daňový úrad|exekúc","safeacc":"bezpečný účet|bezpečného účtu|preveďte|previesť peniaze","prize":"vyhral|výhr|gratul|odmen|darček|zadarmo|losovan","family":"ahoj mami|ahoj oci|ahoj babi|ahoj dedo|nové číslo|rozbil|stratil|pošli mi|potrebujem peniaze","money":"peniaze|peňazí|pošli|pošlite|prevod|preveď|požičaj","remote":"anydesk|teamviewer|rustdesk|vzdialen|nainštalujte|stiahnite aplikáciu","invest":"investíci|investov|krypto|bitcoin|výnos|zaručen|zbohatn|pasívny príjem"}};
